macro_rules! sum10015 {
    ($($item:expr),+ $(,)?) => { 0 $(+ $item)+ };
}

pub fn fold10015(values: &[i32]) -> i32 {
    let literal = sum10015!(55, 56);
    values.iter().filter(|v| **v >= 0).fold(literal, |acc, v| acc + *v)
}
